import fs from "node:fs";

const serverPath = new URL(
  "./server.js",
  import.meta.url
);
const phase10Path = new URL(
  "./phase10-bootstrap.mjs",
  import.meta.url
);

let server = fs.readFileSync(
  serverPath,
  "utf8"
);

const MARKER =
  "JOSHUA_PHASE20_SECURE_TEAM_LOGIN_V1";

if (!server.includes(MARKER)) {
  if (
    !server.includes(
      'import path from "node:path";'
    )
  ) {
    throw new Error(
      "Could not locate Joshua's server import section for Phase 20."
    );
  }

  if (
    !server.includes(
      'import crypto from "node:crypto";'
    )
  ) {
    server = server.replace(
      'import path from "node:path";',
      'import path from "node:path";\nimport crypto from "node:crypto";'
    );
  }

  /*
   * JOSHUA_PHASE20_CONTROL_DATA_READER_COMPATIBILITY_V2
   * Newer Joshua builds already preserve unknown persistent fields by
   * spreading `parsed` inside readControlData(). Accept that implementation
   * instead of requiring an older exact return-object shape.
   */
  const readerStart =
    server.indexOf("function readControlData() {");
  const writerStart =
    server.indexOf(
      "\nfunction writeControlData",
      readerStart
    );

  if (
    readerStart < 0 ||
    writerStart < 0
  ) {
    throw new Error(
      "Could not locate Joshua's control-data reader for Phase 20 persistence."
    );
  }

  let readerBlock = server.slice(
    readerStart,
    writerStart
  );

  if (
    !/\.\.\.parsed\s*,/.test(
      readerBlock
    )
  ) {
    const parsedDeclaration =
      readerBlock.indexOf(
        "const parsed = JSON.parse"
      );
    const returnObject =
      readerBlock.indexOf(
        "return {",
        parsedDeclaration
      );

    if (
      parsedDeclaration < 0 ||
      returnObject < 0
    ) {
      throw new Error(
        "Joshua's control-data reader does not expose a safe persistent-data return object."
      );
    }

    const insertionPoint =
      returnObject +
      "return {".length;

    readerBlock =
      readerBlock.slice(0, insertionPoint) +
      '\n      // JOSHUA_PHASE20_PRESERVE_EXTENDED_CONTROL_DATA_V1' +
      '\n      ...parsed,' +
      readerBlock.slice(insertionPoint);

    server =
      server.slice(0, readerStart) +
      readerBlock +
      server.slice(writerStart);
  }

  const controlAuthAnchor =
    'function controlAuthorized(request) {\n  if (!controlPanelKey) return false;\n  const headerKey = String(request.headers["x-control-panel-key"] || "");\n  const queryKey = String(request.query?.key || "");\n  const auth = String(request.headers.authorization || "");\n  const bearer = auth.startsWith("Bearer ") ? auth.slice(7) : "";\n  return [headerKey, queryKey, bearer].some(value => value && value === controlPanelKey);\n}';

  if (!server.includes(controlAuthAnchor)) {
    throw new Error(
      "Could not locate Joshua's shared-key authorization function for Phase 20."
    );
  }

  const helpers = "/* JOSHUA_PHASE20_SECURE_TEAM_LOGIN_V1 */\nconst PHASE20_SESSION_COOKIE = \"joshua_session\";\nconst PHASE20_IDLE_SESSION_HOURS = Number(\n  process.env.PHASE20_IDLE_SESSION_HOURS || 12\n);\nconst PHASE20_ABSOLUTE_SESSION_DAYS = Number(\n  process.env.PHASE20_ABSOLUTE_SESSION_DAYS || 7\n);\nconst PHASE20_PASSWORD_MIN_LENGTH = 10;\nconst phase20LoginAttempts = new Map();\n\nconst PHASE20_ROLE_LABELS = {\n  admin: \"Administrator\",\n  operations: \"Operations\",\n  accounting: \"Accounting\",\n  technician: \"Technician\"\n};\n\nfunction phase20NowIso() {\n  return new Date().toISOString();\n}\n\nfunction phase20Id(prefix = \"phase20\") {\n  return [\n    prefix,\n    Date.now(),\n    crypto.randomBytes(5).toString(\"hex\")\n  ].join(\"-\");\n}\n\nfunction phase20NormalizeUsername(value = \"\") {\n  return String(value || \"\")\n    .trim()\n    .toLowerCase()\n    .replace(/\\s+/g, \".\");\n}\n\nfunction phase20ValidUsername(value = \"\") {\n  return /^[a-z0-9][a-z0-9._-]{2,39}$/.test(\n    phase20NormalizeUsername(value)\n  );\n}\n\nfunction phase20ValidRole(value = \"\") {\n  return Object.prototype.hasOwnProperty.call(\n    PHASE20_ROLE_LABELS,\n    String(value || \"\").toLowerCase()\n  );\n}\n\nfunction phase20SafeEqual(left = \"\", right = \"\") {\n  const a = Buffer.from(String(left), \"utf8\");\n  const b = Buffer.from(String(right), \"utf8\");\n\n  return (\n    a.length === b.length &&\n    crypto.timingSafeEqual(a, b)\n  );\n}\n\nfunction phase20PasswordError(password = \"\") {\n  const value = String(password || \"\");\n\n  if (value.length < PHASE20_PASSWORD_MIN_LENGTH) {\n    return `Password must contain at least ${PHASE20_PASSWORD_MIN_LENGTH} characters.`;\n  }\n\n  if (!/[A-Za-z]/.test(value) || !/\\d/.test(value)) {\n    return \"Password must contain at least one letter and one number.\";\n  }\n\n  return \"\";\n}\n\nfunction phase20HashPassword(password = \"\") {\n  const salt = crypto.randomBytes(16).toString(\"hex\");\n  const hash = crypto\n    .scryptSync(String(password), salt, 64)\n    .toString(\"hex\");\n\n  return \"scrypt$\" + salt + \"$\" + hash;\n}\n\nfunction phase20VerifyPassword(password = \"\", stored = \"\") {\n  const [algorithm, salt, expectedHex] =\n    String(stored || \"\").split(\"$\");\n\n  if (\n    algorithm !== \"scrypt\" ||\n    !salt ||\n    !expectedHex\n  ) {\n    return false;\n  }\n\n  try {\n    const actual = crypto.scryptSync(\n      String(password),\n      salt,\n      64\n    );\n    const expected = Buffer.from(\n      expectedHex,\n      \"hex\"\n    );\n\n    return (\n      actual.length === expected.length &&\n      crypto.timingSafeEqual(actual, expected)\n    );\n  } catch {\n    return false;\n  }\n}\n\nfunction phase20EnsureAuthData(data) {\n  data.auth =\n    data.auth && typeof data.auth === \"object\"\n      ? data.auth\n      : {};\n\n  const auth = data.auth;\n\n  auth.version = 1;\n  auth.users = Array.isArray(auth.users)\n    ? auth.users\n    : [];\n  auth.sessions = Array.isArray(auth.sessions)\n    ? auth.sessions\n    : [];\n  auth.audit = Array.isArray(auth.audit)\n    ? auth.audit\n    : [];\n\n  const now = Date.now();\n\n  auth.sessions = auth.sessions.filter(session => {\n    const idle = new Date(\n      session.expiresAt || 0\n    ).getTime();\n    const absolute = new Date(\n      session.absoluteExpiresAt || 0\n    ).getTime();\n\n    return (\n      idle > now &&\n      absolute > now\n    );\n  });\n\n  auth.audit = auth.audit.slice(0, 2000);\n\n  return auth;\n}\n\nfunction phase20HasAdministrator(data = null) {\n  const source = data || readControlData();\n  const auth = phase20EnsureAuthData(source);\n\n  return auth.users.some(user =>\n    user.enabled !== false &&\n    user.role === \"admin\"\n  );\n}\n\nfunction phase20PublicUser(user = {}) {\n  return {\n    id: user.id,\n    username: user.username,\n    displayName: user.displayName,\n    email: user.email || \"\",\n    role: user.role,\n    roleLabel:\n      PHASE20_ROLE_LABELS[user.role] ||\n      user.role,\n    enabled: user.enabled !== false,\n    forcePasswordChange:\n      user.forcePasswordChange === true,\n    linkedTechnician:\n      user.linkedTechnician || \"\",\n    createdAt: user.createdAt || \"\",\n    updatedAt: user.updatedAt || \"\",\n    lastLoginAt: user.lastLoginAt || \"\"\n  };\n}\n\nfunction phase20RequestIp(request) {\n  return String(\n    request.ip ||\n    request.headers[\"x-forwarded-for\"] ||\n    request.socket?.remoteAddress ||\n    \"\"\n  )\n    .split(\",\")[0]\n    .trim();\n}\n\nfunction phase20RequestUserAgent(request) {\n  return String(\n    request.headers[\"user-agent\"] || \"\"\n  ).slice(0, 300);\n}\n\nfunction phase20ParseCookies(request) {\n  const header = String(\n    request.headers.cookie || \"\"\n  );\n  const cookies = {};\n\n  for (const item of header.split(\";\")) {\n    const separator = item.indexOf(\"=\");\n    if (separator < 0) continue;\n\n    const key = item\n      .slice(0, separator)\n      .trim();\n    const value = item\n      .slice(separator + 1)\n      .trim();\n\n    if (!key) continue;\n\n    try {\n      cookies[key] = decodeURIComponent(value);\n    } catch {\n      cookies[key] = value;\n    }\n  }\n\n  return cookies;\n}\n\nfunction phase20SessionTokenHash(token = \"\") {\n  return crypto\n    .createHash(\"sha256\")\n    .update(String(token), \"utf8\")\n    .digest(\"hex\");\n}\n\nfunction phase20SessionCookie(token = \"\") {\n  const secure =\n    String(publicBaseUrl || \"\")\n      .toLowerCase()\n      .startsWith(\"https://\");\n\n  return [\n    `${PHASE20_SESSION_COOKIE}=${encodeURIComponent(token)}`,\n    \"Path=/\",\n    \"HttpOnly\",\n    \"SameSite=Lax\",\n    secure ? \"Secure\" : \"\",\n    `Max-Age=${Math.max(\n      300,\n      Math.round(\n        PHASE20_ABSOLUTE_SESSION_DAYS *\n        24 *\n        60 *\n        60\n      )\n    )}`\n  ]\n    .filter(Boolean)\n    .join(\"; \");\n}\n\nfunction phase20ClearSessionCookie() {\n  const secure =\n    String(publicBaseUrl || \"\")\n      .toLowerCase()\n      .startsWith(\"https://\");\n\n  return [\n    `${PHASE20_SESSION_COOKIE}=`,\n    \"Path=/\",\n    \"HttpOnly\",\n    \"SameSite=Lax\",\n    secure ? \"Secure\" : \"\",\n    \"Max-Age=0\"\n  ]\n    .filter(Boolean)\n    .join(\"; \");\n}\n\nfunction phase20CreateSession(\n  data,\n  user,\n  request\n) {\n  const auth = phase20EnsureAuthData(data);\n  const token = crypto\n    .randomBytes(32)\n    .toString(\"base64url\");\n  const csrfToken = crypto\n    .randomBytes(24)\n    .toString(\"base64url\");\n  const createdAt = new Date();\n  const absoluteExpiresAt = new Date(\n    createdAt.getTime() +\n    PHASE20_ABSOLUTE_SESSION_DAYS *\n      24 *\n      60 *\n      60 *\n      1000\n  );\n  const expiresAt = new Date(\n    Math.min(\n      absoluteExpiresAt.getTime(),\n      createdAt.getTime() +\n        PHASE20_IDLE_SESSION_HOURS *\n          60 *\n          60 *\n          1000\n    )\n  );\n\n  const session = {\n    id: phase20Id(\"session\"),\n    userId: user.id,\n    tokenHash:\n      phase20SessionTokenHash(token),\n    csrfToken,\n    createdAt:\n      createdAt.toISOString(),\n    lastSeenAt:\n      createdAt.toISOString(),\n    expiresAt:\n      expiresAt.toISOString(),\n    absoluteExpiresAt:\n      absoluteExpiresAt.toISOString(),\n    ip: phase20RequestIp(request),\n    userAgent:\n      phase20RequestUserAgent(request)\n  };\n\n  auth.sessions.push(session);\n  auth.sessions = auth.sessions.slice(-500);\n\n  return {\n    token,\n    session\n  };\n}\n\nfunction phase20AuthenticateRequest(request) {\n  if (\n    request.phase20Auth &&\n    request.phase20Auth.user\n  ) {\n    return request.phase20Auth;\n  }\n\n  const token = phase20ParseCookies(request)[\n    PHASE20_SESSION_COOKIE\n  ];\n\n  if (!token) return null;\n\n  const data = readControlData();\n  const auth = phase20EnsureAuthData(data);\n  const tokenHash =\n    phase20SessionTokenHash(token);\n  const now = Date.now();\n\n  const session = auth.sessions.find(item =>\n    phase20SafeEqual(\n      item.tokenHash || \"\",\n      tokenHash\n    )\n  );\n\n  if (!session) return null;\n\n  const expiresAt = new Date(\n    session.expiresAt || 0\n  ).getTime();\n  const absoluteExpiresAt = new Date(\n    session.absoluteExpiresAt || 0\n  ).getTime();\n\n  if (\n    expiresAt <= now ||\n    absoluteExpiresAt <= now\n  ) {\n    auth.sessions = auth.sessions.filter(\n      item => item.id !== session.id\n    );\n    writeControlData(data);\n    return null;\n  }\n\n  const user = auth.users.find(item =>\n    item.id === session.userId &&\n    item.enabled !== false\n  );\n\n  if (!user) return null;\n\n  const lastSeen = new Date(\n    session.lastSeenAt || 0\n  ).getTime();\n\n  if (\n    !Number.isFinite(lastSeen) ||\n    now - lastSeen > 5 * 60 * 1000\n  ) {\n    session.lastSeenAt =\n      new Date(now).toISOString();\n    session.expiresAt =\n      new Date(\n        Math.min(\n          absoluteExpiresAt,\n          now +\n            PHASE20_IDLE_SESSION_HOURS *\n              60 *\n              60 *\n              1000\n        )\n      ).toISOString();\n    writeControlData(data);\n  }\n\n  request.phase20Auth = {\n    user,\n    session,\n    data\n  };\n  request.phase20User =\n    phase20PublicUser(user);\n\n  return request.phase20Auth;\n}\n\nfunction phase20CsrfValid(\n  request,\n  authentication\n) {\n  const received = String(\n    request.headers[\"x-csrf-token\"] || \"\"\n  );\n\n  return phase20SafeEqual(\n    received,\n    authentication?.session?.csrfToken || \"\"\n  );\n}\n\nfunction phase20LegacyKeyFromRequest(request) {\n  return String(\n    request.headers[\"x-control-panel-key\"] ||\n    request.query?.key ||\n    request.body?.setupKey ||\n    request.body?.key ||\n    \"\"\n  );\n}\n\nfunction phase20LegacyKeyValid(request) {\n  return Boolean(\n    controlPanelKey &&\n    phase20SafeEqual(\n      phase20LegacyKeyFromRequest(request),\n      controlPanelKey\n    )\n  );\n}\n\nfunction phase20RecordAudit(\n  data,\n  {\n    user = null,\n    action = \"activity\",\n    result = \"success\",\n    request = null,\n    detail = \"\",\n    target = \"\"\n  } = {}\n) {\n  const auth = phase20EnsureAuthData(data);\n  const actor = user\n    ? phase20PublicUser(user)\n    : null;\n\n  const item = {\n    id: phase20Id(\"audit\"),\n    createdAt: phase20NowIso(),\n    action,\n    result,\n    userId: actor?.id || \"\",\n    username: actor?.username || \"\",\n    displayName:\n      actor?.displayName || \"\",\n    role: actor?.role || \"\",\n    method:\n      String(request?.method || \"\"),\n    path:\n      String(\n        request?.raw?.url ||\n        request?.url ||\n        \"\"\n      ).split(\"?\")[0],\n    ip: request\n      ? phase20RequestIp(request)\n      : \"\",\n    userAgent: request\n      ? phase20RequestUserAgent(request)\n      : \"\",\n    detail:\n      String(detail || \"\").slice(0, 800),\n    target:\n      String(target || \"\").slice(0, 200)\n  };\n\n  auth.audit.unshift(item);\n  auth.audit = auth.audit.slice(0, 2000);\n\n  return item;\n}\n\nfunction phase20FindUser(\n  data,\n  usernameOrEmail = \"\"\n) {\n  const needle =\n    String(usernameOrEmail || \"\")\n      .trim()\n      .toLowerCase();\n\n  return phase20EnsureAuthData(data)\n    .users\n    .find(user =>\n      String(user.username || \"\")\n        .toLowerCase() === needle ||\n      String(user.email || \"\")\n        .toLowerCase() === needle\n    );\n}\n\nfunction phase20NewUser({\n  username,\n  displayName,\n  email = \"\",\n  role,\n  password,\n  linkedTechnician = \"\",\n  forcePasswordChange = true\n}) {\n  return {\n    id: phase20Id(\"user\"),\n    username:\n      phase20NormalizeUsername(username),\n    displayName:\n      String(displayName || \"\").trim(),\n    email:\n      String(email || \"\").trim(),\n    role:\n      String(role || \"\").toLowerCase(),\n    passwordHash:\n      phase20HashPassword(password),\n    enabled: true,\n    forcePasswordChange:\n      Boolean(forcePasswordChange),\n    linkedTechnician:\n      String(linkedTechnician || \"\").trim(),\n    createdAt: phase20NowIso(),\n    updatedAt: phase20NowIso(),\n    lastLoginAt: \"\"\n  };\n}\n\nfunction phase20ValidateNewUser(\n  data,\n  body = {}\n) {\n  const username =\n    phase20NormalizeUsername(body.username);\n  const displayName =\n    String(body.displayName || \"\").trim();\n  const role =\n    String(body.role || \"\").toLowerCase();\n  const password =\n    String(\n      body.temporaryPassword ||\n      body.password ||\n      \"\"\n    );\n\n  if (!phase20ValidUsername(username)) {\n    return {\n      error:\n        \"Username must contain 3–40 lowercase letters, numbers, periods, underscores or hyphens.\"\n    };\n  }\n\n  if (!displayName) {\n    return {\n      error: \"Display name is required.\"\n    };\n  }\n\n  if (!phase20ValidRole(role)) {\n    return {\n      error: \"Select a valid role.\"\n    };\n  }\n\n  const passwordError =\n    phase20PasswordError(password);\n\n  if (passwordError) {\n    return {\n      error: passwordError\n    };\n  }\n\n  const duplicate =\n    phase20EnsureAuthData(data)\n      .users\n      .some(user =>\n        String(user.username || \"\")\n          .toLowerCase() === username ||\n        (\n          body.email &&\n          String(user.email || \"\")\n            .toLowerCase() ===\n          String(body.email)\n            .trim()\n            .toLowerCase()\n        )\n      );\n\n  if (duplicate) {\n    return {\n      error:\n        \"That username or email is already in use.\"\n    };\n  }\n\n  return {\n    value: {\n      username,\n      displayName,\n      email:\n        String(body.email || \"\").trim(),\n      role,\n      password,\n      linkedTechnician:\n        String(\n          body.linkedTechnician || \"\"\n        ).trim()\n    }\n  };\n}\n\nfunction phase20LoginAttemptKey(\n  request,\n  username = \"\"\n) {\n  return [\n    phase20RequestIp(request),\n    phase20NormalizeUsername(username)\n  ].join(\"|\");\n}\n\nfunction phase20LoginBlocked(\n  request,\n  username = \"\"\n) {\n  const key =\n    phase20LoginAttemptKey(\n      request,\n      username\n    );\n  const current =\n    phase20LoginAttempts.get(key);\n\n  if (!current) return false;\n\n  if (\n    Date.now() -\n      current.firstFailureAt >\n    15 * 60 * 1000\n  ) {\n    phase20LoginAttempts.delete(key);\n    return false;\n  }\n\n  return current.count >= 5;\n}\n\nfunction phase20RecordLoginFailure(\n  request,\n  username = \"\"\n) {\n  const key =\n    phase20LoginAttemptKey(\n      request,\n      username\n    );\n  const current =\n    phase20LoginAttempts.get(key);\n  const now = Date.now();\n\n  if (\n    !current ||\n    now -\n      current.firstFailureAt >\n      15 * 60 * 1000\n  ) {\n    phase20LoginAttempts.set(key, {\n      count: 1,\n      firstFailureAt: now\n    });\n    return;\n  }\n\n  current.count += 1;\n  phase20LoginAttempts.set(key, current);\n}\n\nfunction phase20ClearLoginFailures(\n  request,\n  username = \"\"\n) {\n  phase20LoginAttempts.delete(\n    phase20LoginAttemptKey(\n      request,\n      username\n    )\n  );\n}\n\nfunction phase20Pathname(request) {\n  return String(\n    request.raw?.url ||\n    request.url ||\n    \"\"\n  ).split(\"?\")[0];\n}\n\nfunction phase20TechnicianIdentity(user = {}) {\n  return String(\n    user.linkedTechnician ||\n    user.displayName ||\n    \"\"\n  )\n    .trim()\n    .toLowerCase();\n}\n\nfunction phase20TechnicianOwnsWorkOrder(\n  data,\n  user,\n  trackingNumber\n) {\n  const identity =\n    phase20TechnicianIdentity(user);\n  const tracking =\n    String(trackingNumber || \"\")\n      .replace(/\\D/g, \"\");\n  const item =\n    data.workOrders?.[tracking];\n\n  if (!identity || !item) return false;\n\n  return [\n    item.technician,\n    item.assignedTechnician,\n    item.technicianName\n  ].some(value =>\n    String(value || \"\")\n      .trim()\n      .toLowerCase() === identity\n  );\n}\n\nfunction phase20TechnicianOwnsTask(\n  data,\n  user,\n  taskId\n) {\n  const identity =\n    phase20TechnicianIdentity(user);\n  const task = (data.tasks || []).find(\n    item =>\n      String(item.id) ===\n      String(taskId)\n  );\n\n  if (!task || !identity) return false;\n\n  const assigned =\n    String(task.assignedTo || \"\")\n      .trim()\n      .toLowerCase();\n\n  return (\n    assigned === identity ||\n    (\n      task.trackingNumber &&\n      phase20TechnicianOwnsWorkOrder(\n        data,\n        user,\n        task.trackingNumber\n      )\n    )\n  );\n}\n\nfunction phase20AccountingWriteAllowed(\n  pathname,\n  body = {}\n) {\n  if (\n    /^\\/api\\/control\\/tasks\\/[^/]+\\/(?:acknowledge|complete)$/.test(\n      pathname\n    )\n  ) {\n    return true;\n  }\n\n  if (\n    pathname ===\n    \"/api/control/accountability/run\"\n  ) {\n    return true;\n  }\n\n  if (\n    /billing|invoice|proposal|quote/i.test(\n      pathname\n    )\n  ) {\n    return true;\n  }\n\n  const action =\n    String(\n      body.action ||\n      body.actionType ||\n      \"\"\n    ).toLowerCase();\n\n  return [\n    \"prepare_invoice\",\n    \"mark_invoice_submitted\",\n    \"invoice_submitted\",\n    \"follow_up_proposal\",\n    \"mark_proposal_submitted\",\n    \"proposal_submitted\"\n  ].includes(action);\n}\n\nfunction phase20PermissionAllowed(\n  user,\n  request\n) {\n  if (!user || user.enabled === false) {\n    return false;\n  }\n\n  if (user.role === \"admin\") {\n    return true;\n  }\n\n  const pathname =\n    phase20Pathname(request);\n  const method =\n    String(request.method || \"GET\")\n      .toUpperCase();\n  const write =\n    ![\"GET\", \"HEAD\", \"OPTIONS\"].includes(\n      method\n    );\n\n  if (user.role === \"operations\") {\n    if (\n      pathname.startsWith(\n        \"/api/control/accountability/settings\"\n      ) ||\n      pathname.startsWith(\n        \"/api/control/accountability/briefing\"\n      ) ||\n      pathname.startsWith(\n        \"/api/control/settings\"\n      )\n    ) {\n      return false;\n    }\n\n    return true;\n  }\n\n  if (user.role === \"accounting\") {\n    if (!write) {\n      return !(\n        /clockshark-technicians|wishlist/i.test(\n          pathname\n        )\n      );\n    }\n\n    return phase20AccountingWriteAllowed(\n      pathname,\n      request.body || {}\n    );\n  }\n\n  if (user.role === \"technician\") {\n    if (!write) {\n      return [\n        \"/api/control/status\",\n        \"/api/control/accountability/status\"\n      ].includes(pathname);\n    }\n\n    const data = readControlData();\n\n    if (\n      pathname === \"/api/control/ivr\"\n    ) {\n      return phase20TechnicianOwnsWorkOrder(\n        data,\n        user,\n        request.body?.trackingNumber\n      );\n    }\n\n    const taskMatch = pathname.match(\n      /^\\/api\\/control\\/tasks\\/([^/]+)\\/(?:acknowledge|complete)$/\n    );\n\n    if (taskMatch) {\n      return phase20TechnicianOwnsTask(\n        data,\n        user,\n        decodeURIComponent(taskMatch[1])\n      );\n    }\n\n    return false;\n  }\n\n  return false;\n}\n\nfunction phase20FilterControlSummary(\n  summary,\n  user\n) {\n  if (\n    !user ||\n    user.role !== \"technician\"\n  ) {\n    return summary;\n  }\n\n  const identity =\n    phase20TechnicianIdentity(user);\n\n  const workOrders =\n    (summary.workOrders || []).filter(item =>\n      [\n        item.technician,\n        item.assignedTechnician,\n        item.technicianName\n      ].some(value =>\n        String(value || \"\")\n          .trim()\n          .toLowerCase() === identity\n      )\n    );\n\n  const tracking = new Set(\n    workOrders.map(item =>\n      String(item.trackingNumber || \"\")\n    )\n  );\n\n  const openTasks =\n    (summary.openTasks || []).filter(task =>\n      String(task.assignedTo || \"\")\n        .trim()\n        .toLowerCase() === identity ||\n      tracking.has(\n        String(task.trackingNumber || \"\")\n      )\n    );\n\n  const active =\n    (summary.active || []).filter(item =>\n      tracking.has(\n        String(item.trackingNumber || \"\")\n      )\n    );\n\n  const attention =\n    (summary.attentionWorkOrders || [])\n      .filter(item =>\n        tracking.has(\n          String(item.trackingNumber || \"\")\n        )\n      );\n\n  const events =\n    (summary.recentEvents || [])\n      .filter(item =>\n        tracking.has(\n          String(item.trackingNumber || \"\")\n        ) ||\n        String(item.assignedTo || \"\")\n          .trim()\n          .toLowerCase() === identity\n      );\n\n  return {\n    ...summary,\n    workOrders,\n    openTasks,\n    active,\n    activeCount: active.length,\n    attentionWorkOrders: attention,\n    recentEvents: events,\n    failures:\n      (summary.failures || []).filter(item =>\n        tracking.has(\n          String(item.trackingNumber || \"\")\n        )\n      ),\n    metrics: {\n      ...(summary.metrics || {}),\n      openWorkOrders:\n        workOrders.filter(item =>\n          ![\"completed\", \"paid\"].includes(\n            String(item.state || \"\")\n          )\n        ).length,\n      completedToday:\n        workOrders.filter(item =>\n          item.checkOutAt &&\n          new Date(item.checkOutAt)\n            .toISOString()\n            .slice(0, 10) ===\n          new Date()\n            .toISOString()\n            .slice(0, 10)\n        ).length,\n      revenueToday: 0,\n      invoiceBacklog: 0\n    }\n  };\n}\n\nfunction phase20FilterAccountabilityPayload(\n  payload,\n  user\n) {\n  if (\n    !user ||\n    user.role !== \"technician\"\n  ) {\n    return payload;\n  }\n\n  const identity =\n    phase20TechnicianIdentity(user);\n  const tasks =\n    (payload.tasks || []).filter(task =>\n      String(task.assignedTo || \"\")\n        .trim()\n        .toLowerCase() === identity\n    );\n\n  return {\n    ...payload,\n    tasks,\n    metrics: {\n      open: tasks.length,\n      awaitingAcknowledgement:\n        tasks.filter(task =>\n          task.accountabilityStatus ===\n          \"awaiting_acknowledgement\"\n        ).length,\n      acknowledged:\n        tasks.filter(task =>\n          task.accountabilityStatus ===\n          \"acknowledged\"\n        ).length,\n      escalated:\n        tasks.filter(task =>\n          task.accountabilityStatus ===\n          \"escalated\"\n        ).length,\n      overdue:\n        tasks.filter(task =>\n          task.overdue === true\n        ).length,\n      completedToday:\n        Number(\n          payload.metrics?.completedToday || 0\n        )\n    },\n    recentHistory:\n      (payload.recentHistory || [])\n        .filter(item =>\n          String(item.assignedTo || \"\")\n            .trim()\n            .toLowerCase() === identity\n        )\n  };\n}\n\nfunction phase20EscapeHtml(value = \"\") {\n  return String(value)\n    .replaceAll(\"&\", \"&amp;\")\n    .replaceAll(\"<\", \"&lt;\")\n    .replaceAll(\">\", \"&gt;\")\n    .replaceAll('\"', \"&quot;\")\n    .replaceAll(\"'\", \"&#039;\");\n}\n\nfunction phase20PageShell({\n  title,\n  heading,\n  subheading,\n  body,\n  script = \"\"\n}) {\n  return `<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>${phase20EscapeHtml(title)}</title>\n<style>\n:root{color-scheme:dark;--gold:#eab308;--bg:#07101a;--card:#131e2b;--line:#2c4058;--text:#ecf3fa;--muted:#9fb0c7}\n*{box-sizing:border-box}\nbody{margin:0;min-height:100vh;background:radial-gradient(circle at top,#142436,#07101a 52%);font-family:Arial,sans-serif;color:var(--text);display:grid;place-items:center;padding:24px}\n.card{width:min(560px,100%);background:linear-gradient(145deg,#172536,#101925);border:1px solid var(--line);border-radius:18px;padding:26px;box-shadow:0 22px 70px #0009}\n.brand{font-size:13px;color:var(--gold);font-weight:800;letter-spacing:.08em;text-transform:uppercase}\nh1{font-size:28px;margin:10px 0 6px}\np{color:var(--muted);line-height:1.5}\nlabel{display:block;font-size:13px;font-weight:750;margin:14px 0 6px}\ninput,select{width:100%;padding:13px 14px;border:1px solid #405775;border-radius:10px;background:#0a1420;color:#fff;font-size:16px}\nbutton{width:100%;margin-top:18px;padding:13px 16px;border:0;border-radius:10px;background:var(--gold);color:#111827;font-weight:900;font-size:15px;cursor:pointer}\n.optional{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}\n.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.notice{display:none;margin-top:14px;padding:11px;border-radius:10px;background:#482b28;color:#ffd7d0}\n.success{background:#183f32;color:#b8ffdc}\n.small{font-size:12px;color:var(--muted)}\n@media(max-width:560px){.row{grid-template-columns:1fr}.card{padding:21px}}\n</style>\n</head>\n<body>\n<div class=\"card\">\n<div class=\"brand\">Precision Lighting · Joshua</div>\n<h1>${phase20EscapeHtml(heading)}</h1>\n<p>${phase20EscapeHtml(subheading)}</p>\n${body}\n<div id=\"notice\" class=\"notice\"></div>\n</div>\n<script>\nfunction showNotice(message, success=false){\n const box=document.getElementById(\"notice\");\n box.textContent=message||\"\";\n box.className=\"notice\"+(success?\" success\":\"\");\n box.style.display=message?\"block\":\"none\";\n}\n${script}\n</script>\n</body>\n</html>`;\n}\n\nfunction phase20LoginPage() {\n  return phase20PageShell({\n    title: \"Joshua Login\",\n    heading: \"Sign in to Joshua\",\n    subheading:\n      \"Use your individual Precision Lighting office account.\",\n    body: `\n<form id=\"loginForm\">\n<label>Username or email</label>\n<input id=\"username\" autocomplete=\"username\" required>\n<label>Password</label>\n<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required>\n<button type=\"submit\">Sign In</button>\n</form>`,\n    script: `\ndocument.getElementById(\"loginForm\").addEventListener(\"submit\",async event=>{\n event.preventDefault();\n showNotice(\"\");\n const button=event.currentTarget.querySelector(\"button\");\n button.disabled=true;\n button.textContent=\"Signing in…\";\n try{\n  const response=await fetch(\"/api/auth/login\",{\n   method:\"POST\",\n   credentials:\"same-origin\",\n   headers:{\"Content-Type\":\"application/json\"},\n   body:JSON.stringify({\n    username:document.getElementById(\"username\").value,\n    password:document.getElementById(\"password\").value\n   })\n  });\n  const data=await response.json().catch(()=>({}));\n  if(!response.ok)throw new Error(data.error||\"Sign-in failed.\");\n  location.replace(\"/control-panel\");\n }catch(error){\n  showNotice(error.message);\n  button.disabled=false;\n  button.textContent=\"Sign In\";\n }\n});`\n  });\n}\n\nfunction phase20SetupPage() {\n  return phase20PageShell({\n    title: \"Joshua Secure Setup\",\n    heading: \"Create secure team access\",\n    subheading:\n      \"Create Travis's administrator account. Ariana and Shellie can also be created now with temporary passwords.\",\n    body: `\n<form id=\"setupForm\">\n<label>Travis administrator password</label>\n<input id=\"adminPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"${PHASE20_PASSWORD_MIN_LENGTH}\" required>\n<label>Confirm Travis password</label>\n<input id=\"adminConfirm\" type=\"password\" autocomplete=\"new-password\" minlength=\"${PHASE20_PASSWORD_MIN_LENGTH}\" required>\n<div class=\"optional\">\n<strong>Optional office accounts</strong>\n<p class=\"small\">Leave a temporary password blank to create that account later from Team Access.</p>\n<div class=\"row\">\n<div>\n<label>Ariana temporary password</label>\n<input id=\"arianaPassword\" type=\"password\" autocomplete=\"new-password\">\n</div>\n<div>\n<label>Shellie temporary password</label>\n<input id=\"shelliePassword\" type=\"password\" autocomplete=\"new-password\">\n</div>\n</div>\n</div>\n<button type=\"submit\">Create Secure Accounts</button>\n</form>`,\n    script: `\ndocument.getElementById(\"setupForm\").addEventListener(\"submit\",async event=>{\n event.preventDefault();\n showNotice(\"\");\n const adminPassword=document.getElementById(\"adminPassword\").value;\n const confirm=document.getElementById(\"adminConfirm\").value;\n if(adminPassword!==confirm){showNotice(\"The Travis passwords do not match.\");return;}\n const params=new URLSearchParams(location.search);\n const setupKey=params.get(\"key\")||\"\";\n const button=event.currentTarget.querySelector(\"button\");\n button.disabled=true;\n button.textContent=\"Securing Joshua…\";\n try{\n  const response=await fetch(\"/api/auth/setup\",{\n   method:\"POST\",\n   credentials:\"same-origin\",\n   headers:{\"Content-Type\":\"application/json\"},\n   body:JSON.stringify({\n    setupKey,\n    adminPassword,\n    arianaPassword:document.getElementById(\"arianaPassword\").value,\n    shelliePassword:document.getElementById(\"shelliePassword\").value\n   })\n  });\n  const data=await response.json().catch(()=>({}));\n  if(!response.ok)throw new Error(data.error||\"Setup failed.\");\n  history.replaceState(null,\"\",\"/control-panel\");\n  location.replace(\"/control-panel\");\n }catch(error){\n  showNotice(error.message);\n  button.disabled=false;\n  button.textContent=\"Create Secure Accounts\";\n }\n});`\n  });\n}\n\nfunction phase20PasswordChangePage(\n  authentication\n) {\n  const user =\n    authentication.user;\n\n  return phase20PageShell({\n    title: \"Change Temporary Password\",\n    heading: `Welcome, ${user.displayName}`,\n    subheading:\n      \"Create a private password before opening Joshua.\",\n    body: `\n<form id=\"changeForm\">\n<label>Current temporary password</label>\n<input id=\"currentPassword\" type=\"password\" autocomplete=\"current-password\" required>\n<label>New password</label>\n<input id=\"newPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"${PHASE20_PASSWORD_MIN_LENGTH}\" required>\n<label>Confirm new password</label>\n<input id=\"confirmPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"${PHASE20_PASSWORD_MIN_LENGTH}\" required>\n<button type=\"submit\">Change Password and Continue</button>\n</form>`,\n    script: `\nconst csrf=${JSON.stringify(\n  authentication.session.csrfToken\n)};\ndocument.getElementById(\"changeForm\").addEventListener(\"submit\",async event=>{\n event.preventDefault();\n showNotice(\"\");\n const next=document.getElementById(\"newPassword\").value;\n const confirm=document.getElementById(\"confirmPassword\").value;\n if(next!==confirm){showNotice(\"The new passwords do not match.\");return;}\n const button=event.currentTarget.querySelector(\"button\");\n button.disabled=true;\n button.textContent=\"Changing password…\";\n try{\n  const response=await fetch(\"/api/auth/change-password\",{\n   method:\"POST\",\n   credentials:\"same-origin\",\n   headers:{\n    \"Content-Type\":\"application/json\",\n    \"x-csrf-token\":csrf\n   },\n   body:JSON.stringify({\n    currentPassword:document.getElementById(\"currentPassword\").value,\n    newPassword:next\n   })\n  });\n  const data=await response.json().catch(()=>({}));\n  if(!response.ok)throw new Error(data.error||\"Password change failed.\");\n  location.replace(\"/control-panel\");\n }catch(error){\n  showNotice(error.message);\n  button.disabled=false;\n  button.textContent=\"Change Password and Continue\";\n }\n});`\n  });\n}\n\nfunction phase20PanelSessionJson(\n  authentication\n) {\n  const payload = {\n    user:\n      phase20PublicUser(\n        authentication.user\n      ),\n    csrfToken:\n      authentication.session.csrfToken,\n    sessionExpiresAt:\n      authentication.session.expiresAt\n  };\n\n  return JSON.stringify(payload)\n    .replaceAll(\"<\", \"\\\\u003c\")\n    .replaceAll(\">\", \"\\\\u003e\")\n    .replaceAll(\"&\", \"\\\\u0026\");\n}\n\nfunction phase20InjectSession(\n  html,\n  authentication\n) {\n  const script =\n    `<script>window.__JOSHUA_AUTH__=${phase20PanelSessionJson(authentication)};</script>`;\n\n  return html.includes(\"</head>\")\n    ? html.replace(\n        \"</head>\",\n        `${script}\\n</head>`\n      )\n    : script + html;\n}";

  const replacementAuth = `function controlAuthorized(request) {
  const authentication =
    phase20AuthenticateRequest(request);

  return Boolean(
    authentication &&
    authentication.user &&
    authentication.user.enabled !== false
  );
}`;

  server = server.replace(
    controlAuthAnchor,
    helpers + "\n\n" + replacementAuth
  );

  const rootRouteAnchor =
    'app.get("/", async () => ({';

  if (!server.includes(rootRouteAnchor)) {
    throw new Error(
      "Could not locate Joshua's route registration area for Phase 20."
    );
  }

  const routesAndHooks =
    "/* JOSHUA_PHASE20_AUTH_ROUTES_AND_PERMISSIONS_V1 */\napp.get(\n  \"/api/auth/setup-status\",\n  async (request, reply) => {\n    const data = readControlData();\n\n    return reply.send({\n      ok: true,\n      setupRequired:\n        !phase20HasAdministrator(data),\n      sameControlPanelLink: true\n    });\n  }\n);\n\napp.post(\n  \"/api/auth/setup\",\n  async (request, reply) => {\n    const data = readControlData();\n    const auth = phase20EnsureAuthData(data);\n\n    if (phase20HasAdministrator(data)) {\n      return reply.code(409).send({\n        ok: false,\n        error:\n          \"Joshua secure setup is already complete.\"\n      });\n    }\n\n    if (!phase20LegacyKeyValid(request)) {\n      phase20RecordAudit(data, {\n        action: \"setup_failed\",\n        result: \"denied\",\n        request,\n        detail:\n          \"Invalid control-panel setup key.\"\n      });\n      writeControlData(data);\n\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"The secure setup key is invalid.\"\n      });\n    }\n\n    const adminPassword =\n      String(\n        request.body?.adminPassword || \"\"\n      );\n    const passwordError =\n      phase20PasswordError(adminPassword);\n\n    if (passwordError) {\n      return reply.code(400).send({\n        ok: false,\n        error: passwordError\n      });\n    }\n\n    const travis = phase20NewUser({\n      username: \"travis\",\n      displayName: \"Travis\",\n      email:\n        process.env.OWNER_EMAIL ||\n        \"Travis@ThePrecisionLighting.com\",\n      role: \"admin\",\n      password: adminPassword,\n      forcePasswordChange: false\n    });\n\n    auth.users.push(travis);\n\n    const optionalUsers = [\n      {\n        password:\n          String(\n            request.body?.arianaPassword ||\n            \"\"\n          ),\n        username: \"ariana\",\n        displayName: \"Ariana\",\n        email:\n          \"Operations@triplejindustries.com\",\n        role: \"operations\"\n      },\n      {\n        password:\n          String(\n            request.body?.shelliePassword ||\n            \"\"\n          ),\n        username: \"shellie\",\n        displayName: \"Shellie\",\n        email:\n          \"Accounting@theprecisionlighting.com\",\n        role: \"accounting\"\n      }\n    ];\n\n    for (const optional of optionalUsers) {\n      if (!optional.password) continue;\n\n      const optionalError =\n        phase20PasswordError(\n          optional.password\n        );\n\n      if (optionalError) {\n        return reply.code(400).send({\n          ok: false,\n          error:\n            `${optional.displayName}: ${optionalError}`\n        });\n      }\n\n      auth.users.push(\n        phase20NewUser({\n          ...optional,\n          forcePasswordChange: true\n        })\n      );\n    }\n\n    auth.setupCompletedAt =\n      phase20NowIso();\n    auth.setupCompletedBy =\n      \"Travis\";\n\n    const created =\n      phase20CreateSession(\n        data,\n        travis,\n        request\n      );\n\n    phase20RecordAudit(data, {\n      user: travis,\n      action: \"secure_setup_completed\",\n      request,\n      detail:\n        `${auth.users.length} user account(s) created.`\n    });\n\n    writeControlData(data);\n\n    reply.header(\n      \"Set-Cookie\",\n      phase20SessionCookie(created.token)\n    );\n\n    return reply.send({\n      ok: true,\n      user: phase20PublicUser(travis),\n      usersCreated:\n        auth.users.map(phase20PublicUser)\n    });\n  }\n);\n\napp.post(\n  \"/api/auth/login\",\n  async (request, reply) => {\n    const username =\n      String(\n        request.body?.username || \"\"\n      ).trim();\n    const password =\n      String(\n        request.body?.password || \"\"\n      );\n    const data = readControlData();\n\n    if (!phase20HasAdministrator(data)) {\n      return reply.code(409).send({\n        ok: false,\n        setupRequired: true,\n        error:\n          \"Joshua secure setup has not been completed.\"\n      });\n    }\n\n    if (\n      phase20LoginBlocked(\n        request,\n        username\n      )\n    ) {\n      phase20RecordAudit(data, {\n        action: \"login_rate_limited\",\n        result: \"denied\",\n        request,\n        detail:\n          `Login temporarily blocked for ${username}.`\n      });\n      writeControlData(data);\n\n      return reply.code(429).send({\n        ok: false,\n        error:\n          \"Too many unsuccessful attempts. Try again in 15 minutes.\"\n      });\n    }\n\n    const user =\n      phase20FindUser(data, username);\n\n    if (\n      !user ||\n      user.enabled === false ||\n      !phase20VerifyPassword(\n        password,\n        user.passwordHash\n      )\n    ) {\n      phase20RecordLoginFailure(\n        request,\n        username\n      );\n      phase20RecordAudit(data, {\n        user: user || null,\n        action: \"login_failed\",\n        result: \"denied\",\n        request,\n        detail:\n          `Unsuccessful login for ${username}.`\n      });\n      writeControlData(data);\n\n      return reply.code(401).send({\n        ok: false,\n        error:\n          \"The username or password is incorrect.\"\n      });\n    }\n\n    phase20ClearLoginFailures(\n      request,\n      username\n    );\n\n    user.lastLoginAt =\n      phase20NowIso();\n    user.updatedAt =\n      phase20NowIso();\n\n    const created =\n      phase20CreateSession(\n        data,\n        user,\n        request\n      );\n\n    phase20RecordAudit(data, {\n      user,\n      action: \"login_success\",\n      request\n    });\n\n    writeControlData(data);\n\n    reply.header(\n      \"Set-Cookie\",\n      phase20SessionCookie(created.token)\n    );\n\n    return reply.send({\n      ok: true,\n      user: phase20PublicUser(user),\n      requiresPasswordChange:\n        user.forcePasswordChange === true\n    });\n  }\n);\n\napp.get(\n  \"/api/auth/session\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (!authentication) {\n      return reply.code(401).send({\n        ok: false,\n        authenticated: false\n      });\n    }\n\n    return reply.send({\n      ok: true,\n      authenticated: true,\n      user:\n        phase20PublicUser(\n          authentication.user\n        ),\n      csrfToken:\n        authentication.session.csrfToken,\n      expiresAt:\n        authentication.session.expiresAt\n    });\n  }\n);\n\napp.post(\n  \"/api/auth/logout\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (authentication) {\n      if (\n        !phase20CsrfValid(\n          request,\n          authentication\n        )\n      ) {\n        return reply.code(403).send({\n          ok: false,\n          error:\n            \"Security token validation failed.\"\n        });\n      }\n\n      const data =\n        authentication.data;\n      const auth =\n        phase20EnsureAuthData(data);\n\n      auth.sessions =\n        auth.sessions.filter(\n          session =>\n            session.id !==\n            authentication.session.id\n        );\n\n      phase20RecordAudit(data, {\n        user:\n          authentication.user,\n        action: \"logout\",\n        request\n      });\n\n      writeControlData(data);\n    }\n\n    reply.header(\n      \"Set-Cookie\",\n      phase20ClearSessionCookie()\n    );\n\n    return reply.send({\n      ok: true\n    });\n  }\n);\n\napp.post(\n  \"/api/auth/change-password\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (!authentication) {\n      return reply.code(401).send({\n        ok: false,\n        error: \"Sign in required.\"\n      });\n    }\n\n    if (\n      !phase20CsrfValid(\n        request,\n        authentication\n      )\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Security token validation failed.\"\n      });\n    }\n\n    const currentPassword =\n      String(\n        request.body?.currentPassword ||\n        \"\"\n      );\n    const newPassword =\n      String(\n        request.body?.newPassword ||\n        \"\"\n      );\n    const passwordError =\n      phase20PasswordError(newPassword);\n\n    if (passwordError) {\n      return reply.code(400).send({\n        ok: false,\n        error: passwordError\n      });\n    }\n\n    const data =\n      authentication.data;\n    const auth =\n      phase20EnsureAuthData(data);\n    const user =\n      auth.users.find(item =>\n        item.id ===\n        authentication.user.id\n      );\n\n    if (\n      !user ||\n      !phase20VerifyPassword(\n        currentPassword,\n        user.passwordHash\n      )\n    ) {\n      return reply.code(400).send({\n        ok: false,\n        error:\n          \"The current password is incorrect.\"\n      });\n    }\n\n    user.passwordHash =\n      phase20HashPassword(newPassword);\n    user.forcePasswordChange = false;\n    user.passwordChangedAt =\n      phase20NowIso();\n    user.updatedAt =\n      phase20NowIso();\n\n    auth.sessions =\n      auth.sessions.filter(session =>\n        session.userId !== user.id\n      );\n\n    const created =\n      phase20CreateSession(\n        data,\n        user,\n        request\n      );\n\n    phase20RecordAudit(data, {\n      user,\n      action: \"password_changed\",\n      request\n    });\n\n    writeControlData(data);\n\n    reply.header(\n      \"Set-Cookie\",\n      phase20SessionCookie(created.token)\n    );\n\n    return reply.send({\n      ok: true,\n      user: phase20PublicUser(user),\n      csrfToken:\n        created.session.csrfToken\n    });\n  }\n);\n\napp.get(\n  \"/api/auth/users\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (\n      !authentication ||\n      authentication.user.role !== \"admin\"\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Administrator access is required.\"\n      });\n    }\n\n    const auth =\n      phase20EnsureAuthData(\n        authentication.data\n      );\n\n    return reply.send({\n      ok: true,\n      users:\n        auth.users\n          .map(phase20PublicUser)\n          .sort((a, b) =>\n            a.displayName.localeCompare(\n              b.displayName\n            )\n          ),\n      recentAudit:\n        auth.audit.slice(0, 100)\n    });\n  }\n);\n\napp.post(\n  \"/api/auth/users\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (\n      !authentication ||\n      authentication.user.role !== \"admin\"\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Administrator access is required.\"\n      });\n    }\n\n    if (\n      !phase20CsrfValid(\n        request,\n        authentication\n      )\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Security token validation failed.\"\n      });\n    }\n\n    const data =\n      authentication.data;\n    const validation =\n      phase20ValidateNewUser(\n        data,\n        request.body || {}\n      );\n\n    if (validation.error) {\n      return reply.code(400).send({\n        ok: false,\n        error: validation.error\n      });\n    }\n\n    const user =\n      phase20NewUser({\n        ...validation.value,\n        forcePasswordChange: true\n      });\n\n    phase20EnsureAuthData(data)\n      .users\n      .push(user);\n\n    phase20RecordAudit(data, {\n      user:\n        authentication.user,\n      action: \"user_created\",\n      request,\n      target: user.username,\n      detail:\n        `${user.displayName} created with ${user.role} access.`\n    });\n\n    writeControlData(data);\n\n    return reply.send({\n      ok: true,\n      user: phase20PublicUser(user)\n    });\n  }\n);\n\napp.patch(\n  \"/api/auth/users/:id\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (\n      !authentication ||\n      authentication.user.role !== \"admin\"\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Administrator access is required.\"\n      });\n    }\n\n    if (\n      !phase20CsrfValid(\n        request,\n        authentication\n      )\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Security token validation failed.\"\n      });\n    }\n\n    const data =\n      authentication.data;\n    const auth =\n      phase20EnsureAuthData(data);\n    const user =\n      auth.users.find(item =>\n        item.id ===\n        request.params.id\n      );\n\n    if (!user) {\n      return reply.code(404).send({\n        ok: false,\n        error: \"User not found.\"\n      });\n    }\n\n    const nextRole =\n      request.body?.role !== undefined\n        ? String(\n            request.body.role\n          ).toLowerCase()\n        : user.role;\n\n    if (!phase20ValidRole(nextRole)) {\n      return reply.code(400).send({\n        ok: false,\n        error: \"Invalid role.\"\n      });\n    }\n\n    const nextEnabled =\n      request.body?.enabled !== undefined\n        ? (\n            request.body.enabled === true ||\n            request.body.enabled === \"true\"\n          )\n        : user.enabled !== false;\n\n    const activeAdmins =\n      auth.users.filter(item =>\n        item.enabled !== false &&\n        item.role === \"admin\"\n      );\n\n    if (\n      user.role === \"admin\" &&\n      user.enabled !== false &&\n      (\n        nextRole !== \"admin\" ||\n        nextEnabled === false\n      ) &&\n      activeAdmins.length <= 1\n    ) {\n      return reply.code(400).send({\n        ok: false,\n        error:\n          \"Joshua must retain at least one enabled administrator.\"\n      });\n    }\n\n    user.displayName =\n      request.body?.displayName !== undefined\n        ? String(\n            request.body.displayName\n          ).trim()\n        : user.displayName;\n    user.email =\n      request.body?.email !== undefined\n        ? String(\n            request.body.email\n          ).trim()\n        : user.email;\n    user.role = nextRole;\n    user.enabled = nextEnabled;\n    user.linkedTechnician =\n      request.body?.linkedTechnician !==\n      undefined\n        ? String(\n            request.body.linkedTechnician\n          ).trim()\n        : user.linkedTechnician;\n    user.updatedAt =\n      phase20NowIso();\n\n    if (user.enabled === false) {\n      auth.sessions =\n        auth.sessions.filter(session =>\n          session.userId !== user.id\n        );\n    }\n\n    phase20RecordAudit(data, {\n      user:\n        authentication.user,\n      action: \"user_updated\",\n      request,\n      target: user.username,\n      detail:\n        `${user.displayName} updated to ${user.role}; enabled=${user.enabled !== false}.`\n    });\n\n    writeControlData(data);\n\n    return reply.send({\n      ok: true,\n      user: phase20PublicUser(user)\n    });\n  }\n);\n\napp.post(\n  \"/api/auth/users/:id/reset-password\",\n  async (request, reply) => {\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (\n      !authentication ||\n      authentication.user.role !== \"admin\"\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Administrator access is required.\"\n      });\n    }\n\n    if (\n      !phase20CsrfValid(\n        request,\n        authentication\n      )\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Security token validation failed.\"\n      });\n    }\n\n    const newPassword =\n      String(\n        request.body?.temporaryPassword ||\n        \"\"\n      );\n    const passwordError =\n      phase20PasswordError(newPassword);\n\n    if (passwordError) {\n      return reply.code(400).send({\n        ok: false,\n        error: passwordError\n      });\n    }\n\n    const data =\n      authentication.data;\n    const auth =\n      phase20EnsureAuthData(data);\n    const user =\n      auth.users.find(item =>\n        item.id === request.params.id\n      );\n\n    if (!user) {\n      return reply.code(404).send({\n        ok: false,\n        error: \"User not found.\"\n      });\n    }\n\n    user.passwordHash =\n      phase20HashPassword(newPassword);\n    user.forcePasswordChange = true;\n    user.updatedAt =\n      phase20NowIso();\n    user.passwordResetAt =\n      phase20NowIso();\n\n    auth.sessions =\n      auth.sessions.filter(session =>\n        session.userId !== user.id\n      );\n\n    phase20RecordAudit(data, {\n      user:\n        authentication.user,\n      action: \"password_reset\",\n      request,\n      target: user.username,\n      detail:\n        `${user.displayName} received a temporary password and must change it at next login.`\n    });\n\n    writeControlData(data);\n\n    return reply.send({\n      ok: true,\n      user: phase20PublicUser(user)\n    });\n  }\n);\n\napp.addHook(\n  \"preHandler\",\n  async (request, reply) => {\n    const pathname =\n      phase20Pathname(request);\n\n    if (\n      !pathname.startsWith(\n        \"/api/control/\"\n      )\n    ) {\n      return;\n    }\n\n    const authentication =\n      phase20AuthenticateRequest(request);\n\n    if (!authentication) {\n      return reply.code(401).send({\n        ok: false,\n        error: \"Sign in required.\"\n      });\n    }\n\n    if (\n      authentication.user\n        .forcePasswordChange === true\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        passwordChangeRequired: true,\n        error:\n          \"Change your temporary password before using Joshua.\"\n      });\n    }\n\n    if (\n      !phase20PermissionAllowed(\n        authentication.user,\n        request\n      )\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Your Joshua role does not permit this action.\"\n      });\n    }\n\n    const method =\n      String(request.method || \"GET\")\n        .toUpperCase();\n\n    if (\n      ![\"GET\", \"HEAD\", \"OPTIONS\"].includes(\n        method\n      ) &&\n      !phase20CsrfValid(\n        request,\n        authentication\n      )\n    ) {\n      return reply.code(403).send({\n        ok: false,\n        error:\n          \"Security token validation failed. Refresh Joshua and try again.\"\n      });\n    }\n\n    if (\n      ![\"GET\", \"HEAD\", \"OPTIONS\"].includes(\n        method\n      )\n    ) {\n      request.phase20AuditPending = {\n        userId:\n          authentication.user.id,\n        path: pathname\n      };\n    }\n  }\n);\n\napp.addHook(\n  \"onResponse\",\n  async (request, reply) => {\n    if (!request.phase20AuditPending) {\n      return;\n    }\n\n    const data = readControlData();\n    const auth =\n      phase20EnsureAuthData(data);\n    const user =\n      auth.users.find(item =>\n        item.id ===\n        request.phase20AuditPending.userId\n      );\n\n    phase20RecordAudit(data, {\n      user,\n      action: \"control_change\",\n      result:\n        reply.statusCode < 400\n          ? \"success\"\n          : \"failed\",\n      request,\n      detail:\n        `HTTP ${reply.statusCode}`\n    });\n\n    writeControlData(data);\n  }\n);";

  server = server.replace(
    rootRouteAnchor,
    routesAndHooks +
      "\n\n" +
      rootRouteAnchor
  );

  const oldControlPanel = "app.get(\"/control-panel\", async (request, reply) => {\n  if (!controlAuthorized(request)) {\n    return reply\n      .code(401)\n      .type(\"text/html\")\n      .send(\"<h2>Joshua Control Panel</h2><p>Open this page with your secure key: <code>/control-panel?key=YOUR_KEY</code></p>\");\n  }\n  const htmlPath = path.join(process.cwd(), \"public\", \"control-panel.html\");\n  return reply.type(\"text/html\").send(fs.readFileSync(htmlPath, \"utf8\"));\n});";
  const newControlPanel =
    "app.get(\"/control-panel\", async (request, reply) => {\n  const data = readControlData();\n  const setupRequired =\n    !phase20HasAdministrator(data);\n  const authentication =\n    phase20AuthenticateRequest(request);\n\n  if (setupRequired) {\n    if (!phase20LegacyKeyValid(request)) {\n      return reply\n        .code(401)\n        .type(\"text/html\")\n        .send(\n          phase20PageShell({\n            title: \"Joshua Secure Setup\",\n            heading: \"Secure setup key required\",\n            subheading:\n              \"Open the existing Joshua control-panel link that contains your secure key to create the first administrator account.\",\n            body:\n              \"<p class='small'>No office account has been created yet.</p>\"\n          })\n        );\n    }\n\n    return reply\n      .type(\"text/html\")\n      .send(phase20SetupPage());\n  }\n\n  if (!authentication) {\n    return reply\n      .type(\"text/html\")\n      .send(phase20LoginPage());\n  }\n\n  if (\n    authentication.user\n      .forcePasswordChange === true\n  ) {\n    return reply\n      .type(\"text/html\")\n      .send(\n        phase20PasswordChangePage(\n          authentication\n        )\n      );\n  }\n\n  const htmlPath = path.join(\n    process.cwd(),\n    \"public\",\n    \"control-panel.html\"\n  );\n  const html = fs.readFileSync(\n    htmlPath,\n    \"utf8\"\n  );\n\n  return reply\n    .type(\"text/html\")\n    .send(\n      phase20InjectSession(\n        html,\n        authentication\n      )\n    );\n});";

  if (!server.includes(oldControlPanel)) {
    throw new Error(
      "Could not locate Joshua's control-panel route for Phase 20."
    );
  }

  server = server.replace(
    oldControlPanel,
    newControlPanel
  );

  const statusReturn =
    '  return reply.send({ ok: true, ...controlSummary() });';

  if (!server.includes(statusReturn)) {
    throw new Error(
      "Could not locate Joshua's control status response for role filtering."
    );
  }

  server = server.replace(
    statusReturn,
    `  const summary = controlSummary();
  return reply.send({
    ok: true,
    ...phase20FilterControlSummary(
      summary,
      request.phase20User
    )
  });`
  );

  const phase19StatusReturn =
    `    return reply.send(
      phase19StatusPayload()
    );`;

  if (
    server.includes(
      phase19StatusReturn
    )
  ) {
    server = server.replace(
      phase19StatusReturn,
      `    return reply.send(
      phase20FilterAccountabilityPayload(
        phase19StatusPayload(),
        request.phase20User
      )
    );`
    );
  }

  const actorBlock =
    `const actor =
      String(
        request.body?.actor ||
        task.assignedTo ||
        "Office"
      ).trim();`;

  const secureActorBlock =
    `const actor =
      String(
        request.phase20User?.displayName ||
        task.assignedTo ||
        "Office"
      ).trim();`;

  server = server
    .split(actorBlock)
    .join(secureActorBlock);

  fs.writeFileSync(
    serverPath,
    server
  );

  console.log(
    "Joshua Phase 20 secure team authentication backend installed."
  );
}

if (!fs.existsSync(phase10Path)) {
  throw new Error(
    "Could not locate Phase 10 for the final Phase 20 Office Suite UI."
  );
}

let phase10 = fs.readFileSync(
  phase10Path,
  "utf8"
);

const UI_CHAIN_MARKER =
  "JOSHUA_PHASE20_FINAL_UI_CHAIN_V1";

if (!phase10.includes(UI_CHAIN_MARKER)) {
  const finalImport =
    'await import("./server.js");';

  if (!phase10.includes(finalImport)) {
    throw new Error(
      "Could not locate Phase 10's final server import for Phase 20."
    );
  }

  phase10 = phase10.replace(
    finalImport,
    `// ${UI_CHAIN_MARKER}
await import("./phase20-ui-runtime.mjs");`
  );

  fs.writeFileSync(
    phase10Path,
    phase10
  );

  console.log(
    "Joshua Phase 20 final UI runtime connected after Office Suite generation."
  );
}

